import "core-js/modules/es.array.push.js";
import { useDisplay } from "vuetify/lib/framework.mjs";
import LocationApprove from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/LocationApprove.vue";
import DeleteVisitorloc from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/DeleteVisitorloc.vue";
import EditVisitorsLoc from "@/components/VisitsManagementApp/AdminApp/AdminDialogues/EditVisitorsLoc.vue";
import { list_all_visit_locations } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    EditVisitorsLoc,
    DeleteVisitorloc,
    LocationApprove
  },
  data() {
    return {
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      componentCheck: 0,
      height: 0,
      verifiyTab: 1,
      page: 1,
      currentPage: 1,
      totalItems: 0,
      itemsPerPage: 20,
      locationdeletion: false,
      approvalLocation: false,
      headers: [{
        title: "Name",
        value: "location_name",
        sortable: false
      }, {
        title: "Address",
        value: "address_details",
        sortable: false
      }, {
        title: "City",
        value: "city",
        sortable: false
      }, {
        title: "Contact No ",
        value: "mobile_number",
        sortable: false
      }, {
        title: "Ref Id ",
        value: "location_ref_id",
        sortable: false
      }, {
        title: "Territories",
        value: "territory_name",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }],
      tableData: [],
      tableLoading: false,
      fixed: true,
      editvisitorLoaction: false,
      rowInfo: {}
    };
  },
  computed: {
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.CommonVuetifyObj = useDisplay();
    this.fetch_locationtype();
  },
  methods: {
    aprove_location(item) {
      this.componentCheck = 3;
      this.approvalLocation = true;
      this.rowInfo = item;
    },
    edit_location(item) {
      this.componentCheck = 1;
      this.editvisitorLoaction = true;
      this.rowInfo = item;
    },
    delete_location(item) {
      this.componentCheck = 2;
      this.rowInfo = item;
      this.locationdeletion = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.locationdeletion = false;
      this.editvisitorLoaction = false;
      this.approvalLocation = false;
      this.tableData = [];
      this.fetch_locationtype();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_locationtype() {
      this.tableLoading = true;
      this.tableData = [];
      try {
        let result = await API.graphql(graphqlOperation(list_all_visit_locations, {
          input: {
            nextToken: null,
            limit: 100,
            location_verification_status: "UNVERIFIED"
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_all_visit_locations);
        if (response.Status == "SUCCESS") {
          this.tableLoading = false;
          this.tableData = response.data;
          this.totalItems = this.tableData.length;
        }
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.totalItems = 0;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
